hl.on("hyprland.start", function()
    hl.exec_cmd("hyprpm reload -n")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("gnome-keyring-daemon --start --components=secrets")
end)

-- Force set the cursor immediately on startup for all apps/root elements
hl.exec_cmd("hyprctl setcursor Vimix-cursors 13")

-- Sync with GTK applications (GNOME settings daemon)
hl.exec_cmd("gsettings set org.gnome.desktop.interface cursor-theme 'Vimix-cursors'")
hl.exec_cmd("gsettings set org.gnome.desktop.interface cursor-size 13")

